const fs = require('fs');
const path = require('path');
const vmm = require('vm');
const SRC = JSON.parse(fs.readFileSync(path.join(__dirname, 'src_g4s2_science_u4.json'), 'utf8'));
const OUT = path.join(__dirname, '..', 'data', 'g4s2_science_u4.js');
const DIR = '4단원_기후변화와우리생활';
const LIVE = '../../grade4/semester2/science/' + DIR + '/';
const UNIT = 4, UT = '기후 변화와 우리 생활', PREV_KEY = 'g4s2_science:u3_l11';

const TN = (a1, a2, watch, min) => ({ ask: [a1, a2], watch, min });
const nm = (s) => String(s || '').replace(/\*\*/g, '');
const EMO = /[\u{1F000}-\u{1FFFF}\u2600-\u27BF\u2B00-\u2BFF\uFE0F\u200D\u20E3]/gu;
const plain = (s) => nm(s).replace(EMO, '').replace(/\s+/g, ' ').trim();
const S = (k, i) => SRC[k].slides[i];
/* 원문 카드(fx-card) → tools 카드: 「이름 — 아래 줄」이면 첫 「 — 」에서 가름 */
const cardsFig = (sl, chain) => ({ k: chain ? 'chain' : 'tools', items: sl.cards.map(c => { const t = nm(c.label).replace(/\n/g, ' '); const i = t.indexOf(' — '); return i < 0 ? { emoji: c.emoji, name: t } : { emoji: c.emoji, name: t.slice(0, i), kind: t.slice(i + 3) }; }) });
/* 진행형·차시 고유 시뮬 → tools/chain: [그림, 이름, 아래 줄] 모두 원문 시뮬 함수 본문의 글 토막(게이트 F 대조) */
const simFig = (rows, chain) => ({ k: chain ? 'chain' : 'tools', items: rows.map(r => ({ emoji: r[0], name: r[1], kind: r[2] })) });
/* 도감 → tools: 원문 이름·그림 · 아래 줄 = 원문 결과 줄 line 번째의 「 — 」 뒤 */
const featFig = (sl, line, chain) => ({ k: chain ? 'chain' : 'tools', items: Object.values(sl.data.data).map(f => { const t = plain(f.feats[line]); return { emoji: f.emoji, name: f.name, kind: t.slice(t.indexOf(' — ') + 3) }; }) });
/* 도감 → ask 두 갈래 */
const featAsk = (sl, q, yesIds, x) => { const d = sl.data.data; return Object.assign({ k: 'ask', q, yes: Object.keys(d).filter(id => yesIds.indexOf(id) >= 0).map(id => ({ name: d[id].name, emoji: d[id].emoji })), no: Object.keys(d).filter(id => yesIds.indexOf(id) < 0).map(id => ({ name: d[id].name, emoji: d[id].emoji })) }, x || {}); };

/* 카드 없이 말풍선만 있는 원문 정리 장 → tools: 이름 = 원문 말풍선 글 토막(게이트 F 대조) */
const textFig = (sl, rows) => ({ k: 'tools', items: rows.map(r => ({ emoji: r[0], name: r[1] })) });

/* 직전 단원 마지막 차시(4-2 과학 u3_l11 「여러 가지 기체」 마무리) exit */
const PREV_EXIT = (() => { const L = {}; const c = { window: { LESSONS: L } }; c.window.window = c.window; vmm.createContext(c); vmm.runInContext(fs.readFileSync(path.join(__dirname, '..', 'data', 'g4s2_science_u3.js'), 'utf8'), c); return L.u3_l11.slides.find(s => s.block === 'exit_ticket').data.items; })();

